const NARASIMHAVARMAN_INFO={id:"narasimhavarman-i",title:"Narasimhavarman I (Pallava Ruler of Kanchipuram)",reignPeriod:"c. 630 – 668 CE (7th Century)",dynasty:"Pallava Dynasty",capital:"Kanchipuram (Kanchi), Tamil Nadu",titles:"Mamalla (Great Wrestler) & Vatapikonda (Conqueror of Vatapi)",monumentalCenter:"Mamallapuram (Mahabalipuram - UNESCO World Heritage)",militaryCommander:"Paranjothi (Siruthondar Nayanar)",quickStats:[{label:"Reign Period",value:"c. 630 – 668 CE",icon:"👑"},{label:"Royal Title",value:"Mamalla & Vatapikonda",icon:"⚔️"},{label:"Dynasty",value:"Pallava Dynasty",icon:"🏛️"},{label:"Imperial Capital",value:"Kanchipuram (Kanchi)",icon:"📍"},{label:"Rock Monuments",value:"Mamallapuram Rathas",icon:"🛕"},{label:"Famous Pilgrim",value:"Xuanzang (640 CE)",icon:"📜"}]},MAMALLAPURAM_MONUMENTS=[{title:"Pancha Rathas (Five Monolithic Chariots)",style:"Monolithic Rock-Cut Granite Architecture",description:"Five monolithic stone temples carved from single granite boulders, named after the Pandavas (Dharmaraja, Bhima, Arjuna, Nakula-Sahadeva) and Draupadi.",significance:"Represented the evolutionary prototype of Dravidian temple vimanas, gopurams, and pillared mandapas."},{title:"Descent of the Ganges (Arjuna's Penance)",style:"Open-Air Rock Relief (96 x 43 ft)",description:"World's largest open-air stone bas-relief carved on two massive monolithic granite boulders, depicting the celestial descent of river Ganga alongside gods, sages, and lifelike elephants.",significance:"Celebrated as one of the finest masterworks of Indian plastic art and sculptural narrative."},{title:"Cave Temples (Mahishasuramardini & Varaha)",style:"Rock-Cut Excavations",description:"Rock-cut shrine chambers featuring dynamic high-relief sculptures of Goddess Durga defeating the buffalo demon Mahishasura and Lord Vishnu as Varaha lifting Goddess Earth.",significance:"Mastery of expressive kinetic anatomy and mythological storytelling in solid stone."}],VATAPI_CAMPAIGN=[{stage:"Chalukya Incursions (c. 630–635 CE)",detail:"Western Chalukya king Pulakeshin II invaded the northern borders of Pallava kingdom, advancing towards Kanchipuram."},{stage:"Pallava Counteroffensive & Battles",detail:"Narasimhavarman I mobilized Pallava armies, defeating Chalukya forces in decisive pitched battles at Pariyala, Manimangala, and Suramara."},{stage:"Capture of Vatapi & Title 'Vatapikonda' (642 CE)",detail:"Led by Narasimhavarman I and Commander Paranjothi, the Pallava army besieged and captured the Chalukya capital of Vatapi (Badami), defeating Pulakeshin II."},{stage:"Mallikarjuna Temple Inscription",detail:"Inscribed a victory record on a stone pillar behind the Mallikarjuna temple at Badami, commemorating the capture of the city."}],FOREIGN_RELATIONS=[{title:"Xuanzang's Visit to Kanchipuram (640 CE)",record:"Chinese pilgrim Xuanzang spent several months at Kanchi, noting over 100 Buddhist monasteries, 10,000 monks, thriving Vedic learning, and peaceful social order."},{title:"Sri Lanka Naval Expeditions (Manavamma)",record:"Provided two naval fleets to Sri Lankan Prince Manavamma from the port of Mamallapuram, helping him defeat King Dathopatissa II and secure the throne of Anuradhapura."}],TIMELINE_EVENTS=[{year:"c. 630 CE",title:"Accession of Narasimhavarman I",description:"Succeeds his father Mahendravarman I to the throne of Kanchipuram."},{year:"640 CE",title:"Visit of Chinese Pilgrim Xuanzang",description:"Xuanzang arrives in Kanchipuram and records the grandeur of the Pallava capital and educational centers."},{year:"642 CE",title:"Conquest of Vatapi (Badami)",description:"Decisive victory over Chalukya King Pulakeshin II; assumes the victory title 'Vatapikonda'."},{year:"c. 650 CE",title:"Creation of Mamallapuram Rock Monuments",description:"Commissions the Pancha Rathas, Descent of the Ganges relief, and rock-cut cave temples at the port city of Mamallapuram."},{year:"c. 668 CE",title:"Concluding Reign & Legacy",description:"Concludes glorious 38-year reign, establishing Pallava dominance in South India and inspiring Dravidian architecture."}],REFERENCES=[{text:"Gopalan, R. (1928). History of the Pallavas of Kanchi. University of Madras.",link:"#"},{text:"Sastri, K. A. Nilakanta (1955). A History of South India. Oxford University Press.",link:"#"},{text:"Srinivasan, K. R. (1964). Cave-Temples of the Pallavas. Archaeological Survey of India.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={NARASIMHAVARMAN_INFO:NARASIMHAVARMAN_INFO,MAMALLAPURAM_MONUMENTS:MAMALLAPURAM_MONUMENTS,VATAPI_CAMPAIGN:VATAPI_CAMPAIGN,FOREIGN_RELATIONS:FOREIGN_RELATIONS,TIMELINE_EVENTS:TIMELINE_EVENTS,REFERENCES:REFERENCES});